/* Tail retries precede newly authorized base; held base retries block event-only substitution. */
#include "swf_stream_mix_gate_fixture.hpp"
int main(int argc,char **argv)
{
 bool exceptions=argc==1;assert(argc==1||(argc==2&&!strcmp(argv[1],"--no-throw")));
 {GateFixture f;f.fifo.reenter=1;FVM_SWFStreamConverter cursor=f.converter;size_t n=91;f.fifo.fail_count=1;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,0,&n)==FVM_ERROR && !n && !memcmp(&cursor,&f.converter,sizeof(cursor)));f.fifo.fail_count=0;f.fifo.fail_write=1;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,0,&n)==FVM_ERROR && !n);if(exceptions){f.fifo.throw_write=1;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n)==FVM_ERROR && !n);f.fifo.throw_write=0;}f.fifo.fail_write=0;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n)==FVM_OK && n==2 && !memcmp(&cursor,&f.converter,sizeof(cursor)));assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n)==FVM_OK && n==2 && f.fifo.samples[4]==30000 && f.fifo.samples[6]==-25125);}
 {GateFixture f;size_t n=0;f.fifo.fail_write=2;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n)==FVM_NOT_FOUND && !n);FVM_SWFSoundMixQueuePending pending;pending.struct_size=sizeof(pending);assert(fvm_swf_sound_mix_queue_pending(f.mix,&pending)==FVM_OK && pending.origin==FVM_SWF_SOUND_MIX_QUEUE_PENDING_BASE && pending.frames==2);FVM_SWFStreamConverter cursor=f.converter;size_t calls=f.fifo.calls;f.fifo.fail_write=0;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,0,&n)==FVM_NOT_FOUND && !n && f.fifo.calls==calls && !memcmp(&cursor,&f.converter,sizeof(cursor)));assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n)==FVM_OK && n==2 && !memcmp(&cursor,&f.converter,sizeof(cursor)));assert(f.fifo.samples[0]==30000 && f.fifo.samples[2]==-25125);}
 return 0;
}
